package com.commercecore.payment;import jakarta.validation.Valid;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/staff/payments") public class StaffPaymentController{final PaymentService service;public StaffPaymentController(PaymentService s){service=s;}@PostMapping("/{id}/refunds")public PaymentDtos.RefundResponse refund(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody PaymentDtos.RefundRequest req){return service.refund(UUID.fromString(jwt.getSubject()),id,key,req);}@GetMapping("/{id}/refunds")public List<PaymentDtos.RefundResponse> refunds(@PathVariable UUID id){return service.refunds(id);}@GetMapping("/order/{orderId}")public List<PaymentDtos.PaymentResponse> byOrder(@PathVariable UUID orderId){return service.staffPayments(orderId);}@PostMapping("/{id}/reconcile")public PaymentDtos.PaymentResponse reconcile(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return service.reconcile(UUID.fromString(jwt.getSubject()),id);}}
